@@ -0,0 +1,27 @@
+import type {ParseJsonFunction, ResponseType} from './core/options.js';
+import {ParseError, type Response} from './core/response.js';
+
+export const nullableJsonBody = (response: Response, responseType: ResponseType, parseJson: ParseJsonFunction, encoding?: BufferEncoding): unknown => {
+	const {rawBody} = response;
+
+	try {
+		if (responseType === 'text') {
+			return rawBody.toString(encoding);
+		}
+
+		if (responseType === 'json') {
+			return rawBody.length === 0 ? null : parseJson(rawBody.toString(encoding));
+		}
+
+		if (responseType === 'buffer') {
+			return rawBody;
+		}
+	} catch (error) {
+		throw new ParseError(error as Error, response);
+	}
+
+	throw new ParseError({
+		message: `Unknown body type '${responseType as string}'`,
+		name: 'Error',
+	}, response);
+};
diff --git a/test/nullable-json-body.ts b/test/nullable-json-body.ts
new file mode 100644
