--- /dev/null
+++ b/test/nullable-json-body.ts
@@ -0,0 +1,52 @@
+import {Buffer} from 'node:buffer';
+import test from 'ava';
+import {ParseError, parseBody} from '../source/core/response.js';
+import {nullableJsonBody} from '../source/nullable-json-body.js';
+import withServer from './helpers/with-server.js';
+
+test('only empty JSON bodies become null', withServer, async (t, server, got) => {
+	server.get('/', (_request, response) => {
+		response.end();
+	});
+
+	const response = await got('');
+	t.is(nullableJsonBody(response, 'json', JSON.parse), null);
+	t.is(nullableJsonBody(response, 'text', JSON.parse), '');
+	t.is(nullableJsonBody(response, 'buffer', JSON.parse), response.rawBody);
+	t.is(parseBody(response, 'json', JSON.parse), '');
+});
+
+test('non-empty JSON bodies use the supplied encoding and parser', withServer, async (t, server, got) => {
+	server.get('/', (_request, response) => {
+		response.end(Buffer.from('""', 'utf16le'));
+	});
+
+	const response = await got({responseType: 'buffer'});
+	const parseJson = (text: string) => {
+		t.is(text, '""');
+		return JSON.parse(text);
+	};
+
+	t.is(nullableJsonBody(response, 'json', parseJson, 'utf16le'), '');
+});
+
+test('body parsing errors remain ParseErrors', withServer, async (t, server, got) => {
+	server.get('/', (_request, response) => {
+		response.end(' ');
+	});
+
+	const response = await got('');
+	const error = t.throws(() => nullableJsonBody(response, 'json', JSON.parse), {
+		instanceOf: ParseError,
+		code: 'ERR_BODY_PARSE_FAILURE',
+	});
+	t.is(error?.response, response);
+	t.true(error?.cause instanceof SyntaxError);
+
+	// @ts-expect-error Error tests
+	t.throws(() => nullableJsonBody(response, 'invalid', JSON.parse), {
+		instanceOf: ParseError,
+		code: 'ERR_BODY_PARSE_FAILURE',
+		message: /^Unknown body type 'invalid'/,
+	});
+});
